"% Define the open-loop transfer function L(s)
num = [1.8];
den = [1.0, 3.0, 2.0, 0.0];
sys = tf(num, den);

% Compute classical gain and phase margins
% [Gm, Pm, Wcg, Wcp] = margin(sys)
% Gm   : Gain margin (linear scale, > 1 for stable closed loop)
% Pm   : Phase margin (degrees)
% Wcg  : Phase crossover frequency (rad/s), where phase is -180 deg
% Wcp  : Gain crossover frequency (rad/s), where gain is 0 dB (magnitude is 1)
[Gm, Pm, Wcg, Wcp] = margin(sys);

% Convert Gain Margin to decibels
Gm_dB = 20 * log10(Gm);

% Map results to the required struct keys
% w_gc : Gain crossover frequency -> corresponds to Wcp
% w_pc : Phase crossover frequency -> corresponds to Wcg
resultStruct = struct(...
    'gm_db', Gm_dB, ...
    'pm_deg', Pm, ...
    'w_gc', Wcp, ...
    'w_pc', Wcg ...
);

% Encode the struct to JSON
jsonStr = jsonencode(resultStruct);

% Write the JSON string to result.json
fid = fopen('result.json', 'w');
fprintf(fid, '%s', jsonStr);
fclose(fid);"
